import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            int length = Integer.parseInt(sc.nextLine());
            String inputLine = sc.nextLine();
            char[] characters = inputLine.toCharArray();

            int maxLength = 0;
            int totalWords = 0;
            int currentLength = 0;
            int index = 0;

            while (index < length) {
                char ch = characters[index];

                if (ch != '_' && ch != '(' && ch != ')') {
                    currentLength++;
                } else if (ch == '_') {
                    maxLength = Math.max(maxLength, currentLength);
                    currentLength = 0;
                } else if (ch == '(') {
                    maxLength = Math.max(maxLength, currentLength);
                    currentLength = 0;
                    index++;
                    while (index < length && characters[index] != ')' && characters[index] != '_') {
                        if (characters[index] != '_' && characters[index] != '(' && characters[index] != ')') {
                            currentLength++;
                        } else if (characters[index] == '_') {
                            if (currentLength != 0) {
                                totalWords++;
                                currentLength = 0;
                            }
                        } else if (characters[index] == ')') {
                            if (currentLength != 0) {
                                totalWords++;
                                currentLength = 0;
                            }
                            break;
                        }
                        index++;
                    }
                }
                index++;
            }
            maxLength = Math.max(maxLength, currentLength);
            System.out.println(maxLength + " " + totalWords);
        }
        sc.close();
    }
}
